use crate::*;
use super::{plan::Patch,policy};
pub fn check_option(key:&str,v:&Value)->Result<()> {
 let valid=match key {
  "language"=>v=="zh_cn"||v=="en_us",
  "renderDistance"|"simulationDistance"=>v.as_u64().is_some_and(|n|(2..=32).contains(&n)),
  "maxFps"=>v.as_u64().is_some_and(|n|(10..=260).contains(&n)),
  "guiScale"=>v.as_u64().is_some_and(|n|n<=6),
  "resourcePacks"=>v.as_array().is_some_and(|a|a.len()<=32&&a.iter().all(|s|s.as_str().is_some_and(|s|s=="vanilla"||s.strip_prefix("file/").is_some_and(|v|safe_name(v).is_ok())))),
  _=>false};if valid{Ok(())}else{Err(format!("不允许的游戏选项或值：{key}"))}
}
pub fn validate(p:&Patch)->Result<()> {
 if p.set.is_empty()||p.set.len()>100||p.file.len()>240{return Err("配置补丁为空或超过限制".into());}
 if p.file=="options.txt" {if p.format!="properties"{return Err("options.txt 应使用 properties 格式".into());}for (k,v) in &p.set{let val=if let Some(s)=v.as_str(){match k.as_str(){"language"|"lang"=>json!(s),"resourcePacks"=>serde_json::from_str(s).map_err(|_|"资源包顺序 JSON 无效")?,_=>json!(s.parse::<u64>().map_err(|_|"游戏选项必须是整数")?)}}else{v.clone()};check_option(if k=="lang"{"language"}else{k},&val)?;}return Ok(());}
 if !(p.file.starts_with("config/")||p.file.starts_with("defaultconfigs/"))||!matches!(p.format.as_str(),"json"|"properties"|"toml"|"cfg")||!p.file.ends_with(&format!(".{}",p.format)){return Err("配置仅支持 config/defaultconfigs 下 JSON、properties、TOML、CFG 和 options.txt".into());}
 for (k,v) in &p.set{if k.is_empty()||k.len()>120||k.contains(['\n','\r',':','='])||["password","token","apikey","command","exec","script","path","url"].iter().any(|s|k.to_lowercase().contains(s))||(!v.is_boolean()&&!v.is_number()&&!v.is_string())||v.to_string().len()>2000||v.as_str().is_some_and(|s|s.contains(['\n','\r'])){return Err("配置键或值不在安全范围内".into());}}
 Ok(())
}
fn line_patch(text:&str,set:&std::collections::BTreeMap<String,Value>,options:bool)->Result<String>{
 let sep=if options{':'}else{'='};let newline=if text.contains("\r\n"){ "\r\n" }else{"\n"};
 let mut remaining=set.clone();let mut result=Vec::new();
 for line in text.lines(){let pair=line.split_once(sep);if let Some((key,_))=pair {if let Some(v)=remaining.remove(key.trim()){result.push(format!("{}{}{}",key.trim(),sep,v.as_str().map(str::to_owned).unwrap_or(v.to_string())));continue;}if set.contains_key(key.trim()){continue;}}result.push(line.into());}
 result.extend(remaining.iter().map(|(k,v)|format!("{k}{sep}{}",v.as_str().map(str::to_owned).unwrap_or(v.to_string()))));Ok(result.join(newline)+newline)
}
pub fn apply(root:&Path,p:&Patch)->Result<()> {
 validate(p)?;let file=policy::under(root,&p.file)?;
 let old=if file.exists(){Some(std::fs::read(&file).map_err(err)?)}else{None};if old.as_ref().is_some_and(|b|b.len()>2*1024*1024){return Err("配置文件超过 2 MB，请手动处理".into());}
 let text=String::from_utf8(old.clone().unwrap_or_default()).map_err(|_|"配置文件不是 UTF-8")?;
 let output=if p.format=="json" {let mut v:Value=if text.trim().is_empty(){json!({})}else{serde_json::from_str(&text).map_err(|_|"原 JSON 配置无效，未修改")?};let obj=v.as_object_mut().ok_or("JSON 配置必须是对象")?;for(k,v)in &p.set{obj.insert(k.clone(),v.clone());}serde_json::to_string_pretty(&v).map_err(err)?}else if p.format=="toml"{patch_toml(&text,&p.set)?}else{if p.format=="cfg"{let mut seen=std::collections::HashSet::new();for line in text.lines().filter(|s|!s.trim_start().starts_with('#')){if let Some((key,_))=line.split_once('='){if p.set.contains_key(key.trim())&&!seen.insert(key.trim()){return Err("CFG 中同名键跨段重复，请指定无歧义的模板。".into());}}}}line_patch(&text,&p.set,p.file=="options.txt")?};
 if let Some(parent)=file.parent(){std::fs::create_dir_all(parent).map_err(err)?;}
 if let Some(bytes)=&old{std::fs::write(file.with_extension("kxl-agent-backup"),bytes).map_err(err)?;}
 let result=(||{std::fs::write(&file,&output).map_err(err)?;let written=std::fs::read_to_string(&file).map_err(err)?;if p.format=="json"{let _:Value=serde_json::from_str(&written).map_err(err)?;}if p.format=="toml"{let _:toml::Value=toml::from_str(&written).map_err(err)?;}if written!=output{return Err("写入后校验失败".into());}Ok(())})();
 if result.is_err(){if let Some(bytes)=old{std::fs::write(&file,bytes).map_err(err)?;}else{let _=std::fs::remove_file(&file);}}result
}
fn patch_toml(text:&str,set:&std::collections::BTreeMap<String,Value>)->Result<String>{let mut data:toml::Value=if text.trim().is_empty(){toml::Value::Table(toml::map::Map::new())}else{toml::from_str(text).map_err(|_|"原 TOML 配置无效，未修改")?};for(key,value)in set{let parts:Vec<_>=key.split('.').collect();if parts.iter().any(|s|s.is_empty()){return Err("TOML 键路径无效".into());}let mut node=&mut data;for part in &parts[..parts.len()-1]{let table=node.as_table_mut().ok_or("TOML 配置路径不是表")?;node=table.entry((*part).to_string()).or_insert_with(||toml::Value::Table(toml::map::Map::new()));}node.as_table_mut().ok_or("TOML 配置键不在表内")?.insert(parts.last().unwrap().to_string(),toml::Value::try_from(value).map_err(err)?);}toml::to_string_pretty(&data).map_err(err)}
pub fn keybinds(root:&Path)->Result<Value>{let path=super::policy::under(root,"options.txt")?;let text=std::fs::read_to_string(path).unwrap_or_default();let mut keys=std::collections::BTreeMap::<String,Vec<String>>::new();for line in text.lines(){if let Some((key,value))=line.split_once(':'){if key.starts_with("key_")&&value!="key.keyboard.unknown"&&value!="0"{keys.entry(value.into()).or_default().push(key.into());}}}Ok(json!(keys.into_iter().filter(|(_,v)|v.len()>1).map(|(key,actions)|json!({"key":key,"actions":actions,"note":"可能为有意复用，请在游戏中核对。"})).collect::<Vec<_>>()))}
pub fn templates()->Vec<Value>{[include_str!("../../../config/mod-templates/balanced.json"),include_str!("../../../config/mod-templates/low-memory.json"),include_str!("../../../config/mod-templates/sodium-balanced.json")].into_iter().filter_map(|text|serde_json::from_str(text).ok()).collect()}
pub fn check_template(core:&Core,id:&str,template:&str)->Result<()>{let t=templates().into_iter().find(|t|t["id"]==template).ok_or("模板不存在")?;if let Some(required)=t["match"]["modIds"].as_array(){let rows=resources::list(core,&json!({"id":id,"kind":"mods"}))?;for key in required{if !rows.as_array().into_iter().flatten().any(|r|r["enabled"]==true&&r["modIds"].as_array().is_some_and(|a|a.contains(key))){return Err("此模板所需模组尚未安装或未启用，请先核对实例。".into());}}}Ok(())}
pub fn template_patches(id:&str)->Result<Vec<Patch>>{let value=templates().into_iter().find(|v|v["id"]==id).ok_or("配置模板不存在")?;serde_json::from_value(value["patches"].clone()).map_err(err)}
pub fn options(root:&Path,plan:&super::plan::PackPlan)->Result<()> {
 let mut set=plan.options.clone();if let Some(language)=set.remove("language"){game_options::apply_language(root,&plan.minecraft,language.as_str().ok_or("语言无效")?)?;}
 if !set.is_empty(){apply(root,&Patch{file:"options.txt".into(),format:"properties".into(),set})?;}for p in &plan.config_patches{apply(root,p)?;}Ok(())
}
pub fn read(root:&Path,file:&str)->Result<String>{let empty=Patch{file:file.into(),format:if file=="options.txt"{"properties"}else{file.rsplit('.').next().unwrap_or("properties")}.into(),set:std::collections::BTreeMap::from([("language".into(),json!("zh_cn"))])};validate(&empty)?;let path=policy::under(root,file)?;if !path.exists(){return Ok(String::new());}if std::fs::metadata(&path).map_err(err)?.len()>128*1024{return Err("配置过大，请手动查看。".into());}let text=std::fs::read_to_string(path).map_err(err)?;Ok(ai_diagnose::redact(&text))}
#[cfg(test)] mod tests {use super::*;
 #[test]fn toml_cfg_and_keybinds(){let t=tempfile::tempdir().unwrap();std::fs::create_dir(t.path().join("config")).unwrap();std::fs::write(t.path().join("config/a.toml"),"[display]\nother=true\n").unwrap();let p=Patch{file:"config/a.toml".into(),format:"toml".into(),set:std::collections::BTreeMap::from([("display.enabled".into(),json!(false))])};apply(t.path(),&p).unwrap();let value:toml::Value=toml::from_str(&std::fs::read_to_string(t.path().join("config/a.toml")).unwrap()).unwrap();assert_eq!(value["display"]["other"].as_bool(),Some(true));assert_eq!(value["display"]["enabled"].as_bool(),Some(false));let p=Patch{file:"config/a.cfg".into(),format:"cfg".into(),set:std::collections::BTreeMap::from([("enabled".into(),json!(true))])};apply(t.path(),&p).unwrap();assert!(read(t.path(),"config/a.cfg").unwrap().contains("enabled=true"));std::fs::write(t.path().join("options.txt"),"key_a:key.keyboard.r\nkey_b:key.keyboard.r\nkey_c:key.keyboard.unknown\n").unwrap();let rows=keybinds(t.path()).unwrap();assert_eq!(rows[0]["actions"].as_array().unwrap().len(),2);}
 #[test] fn preserves_and_rejects(){let t=tempfile::tempdir().unwrap();std::fs::write(t.path().join("options.txt"),"lang:en_us\nfullscreen:true\n").unwrap();let p=Patch{file:"options.txt".into(),format:"properties".into(),set:std::collections::BTreeMap::from([("lang".into(),json!("zh_cn")),("maxFps".into(),json!(144))])};apply(t.path(),&p).unwrap();let s=std::fs::read_to_string(t.path().join("options.txt")).unwrap();assert!(s.contains("fullscreen:true"));assert!(s.contains("lang:zh_cn"));assert!(t.path().join("options.kxl-agent-backup").exists());let mut bad=p;bad.set.insert("exec".into(),json!("cmd"));assert!(apply(t.path(),&bad).is_err());assert_eq!(std::fs::read_to_string(t.path().join("options.txt")).unwrap(),s);}
 #[test] fn json_and_properties(){let t=tempfile::tempdir().unwrap();for (file,format)in[("config/a.json","json"),("config/a.properties","properties")]{let p=Patch{file:file.into(),format:format.into(),set:std::collections::BTreeMap::from([("enabled".into(),json!(true))])};apply(t.path(),&p).unwrap();assert!(std::fs::read_to_string(t.path().join(file)).unwrap().contains("enabled"));}std::fs::write(t.path().join("config/a.json"),"{bad").unwrap();let p=Patch{file:"config/a.json".into(),format:"json".into(),set:std::collections::BTreeMap::from([("enabled".into(),json!(true))])};assert!(apply(t.path(),&p).is_err());assert_eq!(std::fs::read_to_string(t.path().join("config/a.json")).unwrap(),"{bad");}
}
